content.text:
{
  "name": "Go2四足机器人",
  "name_en": "Go2 Quadruped Robot",
  "manufacturer": "Unitree Robotics",
  "description": "Go2四足机器人是一种小型腿式移动机器人，具有机动行走与远程通信能力，常用于机器人运动控制、感知导航、巡检和人机交互等实验研究。",
  "description_en": "The Go2 quadruped robot is a compact legged mobile robot with agile locomotion and remote communication capabilities. It is commonly used in laboratory research on robot locomotion, perception, navigation, inspection, and human-robot interaction.",
  "actions": [
    {
      "action_name": "auto-make_request",
      "description": "向机器人的WebRTC信令接口发送HTTP请求。",
      "description_en": "Send an HTTP request to the robot's WebRTC signaling interface."
    },
    {
      "action_name": "auto-send_encrypted_sdp",
      "description": "向机器人发送加密的SDP会话协商数据以建立通信。",
      "description_en": "Send encrypted SDP session negotiation data to the robot to establish communication."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与机器人的HTTP通信会话。",
      "description_en": "Close the HTTP communication session with the robot."
    }
  ],
  "tag_hints": [
    "quadruped robot",
    "legged locomotion",
    "mobile robotics",
    "teleoperation",
    "robot communication",
    "WebRTC signaling",
    "inspection robot"
  ]
}

